mapper.select:
SELECT cm.message_id, cm.group_id, cm.sender_id, cm.message_type, cm.content, cm.file_url, cm.file_name, cm.file_size, cm.created_at, u.username AS sender_username, u.avatar_url AS sender_avatar FROM chat_messages cm JOIN users u ON cm.sender_id = u.user_id
AND cm.is_deleted = 0
AND (lower(cm.content) LIKE lower(concat('%', #{keyword}, '%')))
AND cm.group_id = #{groupId}
AND cm.sender_id = #{userId}
ORDER BY cm.created_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1)
FROM chat_messages cm

    AND cm.is_deleted = 0

        AND (lower(cm.content) LIKE lower(concat('%', #{keyword}, '%')))


        AND cm.group_id = #{groupId}


        AND cm.sender_id = #{userId}
